import{_ as t,a as o,o as s,a6 as n}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Social Login","description":"","frontmatter":{"outline":false,"examples":[{"id":"social-login-google","title":"Social Login with Google","description":"Sign in (or sign up) with a Google ID token obtained from Google Identity Services (web) or the Google SDK (mobile).","request":"POST /api/shop/customers/social-login\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\n\\n{\\n  \\"provider\\": \\"google\\",\\n  \\"idToken\\": \\"eyJhbGciOiJSUzI1NiIsImtpZCI6…\\"\\n}\\n","response":"{\\n  \\"id\\": 1782,\\n  \\"_id\\": 1782,\\n  \\"token\\": \\"1550|1LMsQ6hVh0mZ8b0c2Jit4uVWAShoK8TfeOxnjEmG\\",\\n  \\"apiToken\\": \\"rjTLsuOsX5qehio2q1cMeMd6TCaIKofwQ4mb7y2zcy0\\",\\n  \\"firstName\\": \\"Nadia\\",\\n  \\"lastName\\": \\"Rahman\\",\\n  \\"email\\": \\"nadia@example.com\\",\\n  \\"phone\\": null,\\n  \\"isNewCustomer\\": true,\\n  \\"success\\": true,\\n  \\"message\\": \\"Signed in successfully.\\",\\n  \\"code\\": null\\n}\\n"},{"id":"social-login-facebook","title":"Social Login with Facebook","description":"Sign in with a Facebook access token obtained from the Facebook Login SDK.","request":"POST /api/shop/customers/social-login\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\n\\n{\\n  \\"provider\\": \\"facebook\\",\\n  \\"accessToken\\": \\"EAAJZC…\\"\\n}\\n","response":"{\\n  \\"id\\": 1783,\\n  \\"_id\\": 1783,\\n  \\"token\\": \\"1551|8b0c2Jit4uVWAShoK8TfeOxnjEmG1LMsQ6hVh0mZ\\",\\n  \\"apiToken\\": \\"q1cMeMd6TCaIKofwQ4mb7y2zcy0rjTLsuOsX5qehio2\\",\\n  \\"firstName\\": \\"Omar\\",\\n  \\"lastName\\": \\"Ali\\",\\n  \\"email\\": \\"omar@example.com\\",\\n  \\"phone\\": null,\\n  \\"isNewCustomer\\": false,\\n  \\"success\\": true,\\n  \\"message\\": \\"Signed in successfully.\\",\\n  \\"code\\": null\\n}\\n"},{"id":"social-login-linkedin","title":"Social Login with LinkedIn","description":"Sign in with a LinkedIn access token.","request":"POST /api/shop/customers/social-login\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\n\\n{\\n  \\"provider\\": \\"linkedin\\",\\n  \\"accessToken\\": \\"AQV8…\\"\\n}\\n","response":"{\\n  \\"id\\": 1784,\\n  \\"_id\\": 1784,\\n  \\"token\\": \\"1552|4uVWAShoK8TfeOxnjEmG1LMsQ6hVh0mZ8b0c2Jit\\",\\n  \\"apiToken\\": \\"TCaIKofwQ4mb7y2zcy0rjTLsuOsX5qehio2q1cMeMd6\\",\\n  \\"firstName\\": \\"Chen\\",\\n  \\"lastName\\": \\"Wei\\",\\n  \\"email\\": \\"chen@example.com\\",\\n  \\"phone\\": null,\\n  \\"isNewCustomer\\": true,\\n  \\"success\\": true,\\n  \\"message\\": \\"Signed in successfully.\\",\\n  \\"code\\": null\\n}\\n"},{"id":"social-login-invalid","title":"Invalid Token","description":"The provider rejected the token. Obtain a fresh one and retry.","request":"POST /api/shop/customers/social-login\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\n\\n{\\n  \\"provider\\": \\"google\\",\\n  \\"idToken\\": \\"expired-or-tampered-token\\"\\n}\\n","response":"{\\n  \\"id\\": null,\\n  \\"_id\\": null,\\n  \\"token\\": null,\\n  \\"apiToken\\": null,\\n  \\"firstName\\": null,\\n  \\"lastName\\": null,\\n  \\"email\\": null,\\n  \\"phone\\": null,\\n  \\"isNewCustomer\\": null,\\n  \\"success\\": false,\\n  \\"message\\": \\"The social login token is invalid or expired. Please try again.\\",\\n  \\"code\\": \\"SOCIAL_TOKEN_INVALID\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/shop/customers/social-login.md","filePath":"api/rest-api/shop/customers/social-login.md","lastUpdated":1787725411000}'),d={name:"api/rest-api/shop/customers/social-login.md"};function i(a,e,r,c,l,h){return s(),o("div",null,e[0]||(e[0]=[n(`<h1 id="social-login" tabindex="-1">Social Login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social Login&quot;">​</a></h1><p>Sign a customer in — or sign them up on first sight — with a token their app or browser already holds. The client obtains the token from the provider itself (Google Identity Services or the Google SDK, the Facebook Login SDK, or LinkedIn), so there is no browser redirect; the token is verified server-side and a Bearer <code>token</code> is returned, the same credential <a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> answers with.</p><p>One endpoint both signs in and signs up, so the app never has to check first whether the email exists:</p><ul><li>A known provider account signs in.</li><li>A known email links the provider to that account and signs in.</li><li>Neither creates the account, links it, and signs in — <code>isNewCustomer</code> is <code>true</code>.</li></ul><p>Accounts created this way have no password; a customer who wants one uses <a href="/api/rest-api/shop/customers/forgot-password.html">Forgot Password</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/customers/social-login</span></span></code></pre></div><h2 id="supported-providers" tabindex="-1">Supported Providers <a class="header-anchor" href="#supported-providers" aria-label="Permalink to &quot;Supported Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>provider</code></th><th>Token field</th><th>Where the client gets it</th></tr></thead><tbody><tr><td><code>google</code></td><td><code>idToken</code> (preferred) or <code>accessToken</code></td><td>Google Identity Services (web) or the Google SDK (mobile)</td></tr><tr><td><code>facebook</code></td><td><code>accessToken</code></td><td>Facebook Login SDK (web or mobile)</td></tr><tr><td><code>linkedin</code></td><td><code>accessToken</code></td><td>LinkedIn OAuth</td></tr></tbody></table><p>A provider must be enabled and configured under <strong>Configure → Customer → Settings → Social Login</strong> in the admin panel.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key. No Bearer token is needed to call this endpoint.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;google&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;idToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eyJhbGciOiJSUzI1NiIsImtpZCI6…&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>provider</code></td><td>string</td><td>Yes</td><td>One of <code>google</code>, <code>facebook</code>, <code>linkedin</code>.</td></tr><tr><td><code>idToken</code></td><td>string</td><td>Conditional</td><td>Google ID token. Use for <code>google</code>.</td></tr><tr><td><code>accessToken</code></td><td>string</td><td>Conditional</td><td>OAuth access token. Use for <code>facebook</code> and <code>linkedin</code>, or for <code>google</code> when you hold an access token instead of an ID token.</td></tr><tr><td><code>deviceToken</code></td><td>string</td><td>No</td><td>FCM device token to register push in the same call. Applies only when the Bagisto Push Notification package is installed.</td></tr></tbody></table><p>Send <code>idToken</code> for Google, or <code>accessToken</code> for Facebook and LinkedIn — one token is enough.</p><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><p>The response is flat — the token is at the top level. Field names are camelCase.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code> / <code>_id</code></td><td>integer</td><td>Customer ID.</td></tr><tr><td><code>token</code></td><td>string</td><td><strong>The authentication credential.</strong> Format <code>&lt;id&gt;|&lt;secret&gt;</code> — send as <code>Authorization: Bearer &lt;token&gt;</code> on all authenticated requests.</td></tr><tr><td><code>apiToken</code></td><td>string</td><td>Legacy field, kept for backward compatibility. <strong>Not</strong> an auth Bearer.</td></tr><tr><td><code>firstName</code></td><td>string</td><td>Customer first name.</td></tr><tr><td><code>lastName</code></td><td>string</td><td>Customer last name.</td></tr><tr><td><code>email</code></td><td>string</td><td>Customer email.</td></tr><tr><td><code>phone</code></td><td>string</td><td>Customer phone, or <code>null</code> if unset.</td></tr><tr><td><code>isNewCustomer</code></td><td>boolean</td><td><code>true</code> when this call created the account, <code>false</code> when it signed an existing one in.</td></tr><tr><td><code>success</code></td><td>boolean</td><td>Whether sign-in succeeded.</td></tr><tr><td><code>message</code></td><td>string</td><td>Human-readable result.</td></tr><tr><td><code>code</code></td><td>string</td><td>A stable machine-readable error code on failure, <code>null</code> on success. See below.</td></tr></tbody></table><h2 id="error-codes" tabindex="-1">Error Codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error Codes&quot;">​</a></h2><p>Every failure returns <code>success: false</code>, a translated <code>message</code>, and a stable <code>code</code>.</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>SOCIAL_TOKEN_REQUIRED</code></td><td>No <code>idToken</code> / <code>accessToken</code> was sent.</td></tr><tr><td><code>SOCIAL_TOKEN_INVALID</code></td><td>The provider rejected the token — obtain a fresh one and retry.</td></tr><tr><td><code>SOCIAL_TOKEN_AUDIENCE</code></td><td>The Google token was issued for a different app. A configuration mismatch, not retryable.</td></tr><tr><td><code>SOCIAL_EMAIL_REQUIRED</code></td><td>The provider shared no email address. Use email sign-up instead.</td></tr><tr><td><code>ACCOUNT_INACTIVE</code></td><td>The matched account is not activated.</td></tr><tr><td><code>PROVIDER_NOT_SUPPORTED</code></td><td>The <code>provider</code> value is not one of the supported providers.</td></tr><tr><td><code>PROVIDER_DISABLED</code></td><td>The provider is not enabled in the admin panel.</td></tr></tbody></table><h2 id="token-usage" tabindex="-1">Token Usage <a class="header-anchor" href="#token-usage" aria-label="Permalink to &quot;Token Usage&quot;">​</a></h2><p>Send the returned <code>token</code> on customer-scoped requests:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Authorization:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1550</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1LMsQ6hVh0mZ8b0c2Jit4uVWAShoK8TfeOxnjEmG</span></span></code></pre></div><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> — email and password sign-in returning the same token.</li><li><a href="/api/rest-api/shop/customers/forgot-password.html">Forgot Password</a> — set a password on a social account.</li><li><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Customer Profile</a> — read the authenticated customer&#39;s account details.</li></ul>`,27)]))}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
